/**
 * Build Guides for the Character Builder's guide path.
 *
 * A Build Guide is any Actor in an Actor compendium carrying `flags.vagabond.buildGuide` with a `classId`
 * (the system's Build Guides pack is generated by scripts/build-guides/generate.mjs). The flag holds the plan:
 * `{ title, className, classId, startingPackId, stats: {1, 10}, perks: [{level, perkIds}], spells: {startIds, laterIds} }`.
 * Everything else (Training, gear, coins, art) is read from the Actor itself.
 *
 * Documents are referenced by compendium id, never by name (translated worlds rename everything).
 */
import { CurrencyHelper } from '../../../helpers/currency-helper.mjs';

export class BuildGuideService {
  /** @type {Promise<object[]>|null} */
  static #cache = null;

  /** @type {Map<string, Promise<Actor|null>>} guide Actor documents by uuid */
  static #actors = new Map();

  /** Compendium uuid of a system pack document from its id */
  static packUuid(pack, id) {
    return id ? `Compendium.vagabond.${pack}.Item.${id}` : null;
  }

  /**
   * Every Build Guide in the Actor compendiums (index entries, cached for the session).
   * @param {object} [options]
   * @param {boolean} [options.force] - re-read the indexes
   * @returns {Promise<Array<{uuid: string, id: string, name: string, img: string, plan: object}>>}
   */
  static async loadGuides({ force = false } = {}) {
    if (!this.#cache || force) this.#cache = this.#readIndexes();
    return this.#cache;
  }

  static async #readIndexes() {
    const guides = [];
    for (const pack of game.packs.filter(p => p.documentName === 'Actor')) {
      try {
        const index = await pack.getIndex({ fields: ['img', 'flags.vagabond.buildGuide'] });
        for (const entry of index) {
          const plan = entry.flags?.vagabond?.buildGuide;
          if (!plan?.classId) continue;
          guides.push({
            uuid: entry.uuid ?? `Compendium.${pack.collection}.Actor.${entry._id}`,
            id: entry._id,
            name: entry.name,
            img: entry.img,
            plan
          });
        }
      } catch (error) {
        console.warn(`Vagabond | Build Guides: could not read ${pack.collection}`, error);
      }
    }
    return guides.sort((a, b) => a.name.localeCompare(b.name, game.i18n.lang));
  }

  /**
   * Trained Skill keys of a guide Actor (Class Training included; the builder skips the granted ones).
   * @param {Actor} actor
   * @returns {string[]}
   */
  static trainedSkills(actor) {
    return Object.entries(actor?.system?.skills ?? {}).filter(([, s]) => s?.trained).map(([key]) => key);
  }

  /**
   * Item data the guide carries over at Finish: its equipment (Starting Pack, trade-ins and purchases already
   * resolved by the generator, equip states and stacks included).
   * @param {Actor} actor
   * @returns {object[]}
   */
  static equipmentData(actor) {
    // Fresh ids: the data joins the Hero's `items` array in one Actor update, which matches entries by _id
    return actor.items.filter(i => i.type === 'equipment').map(i => ({ ...i.toObject(), _id: foundry.utils.randomID() }));
  }

  /* ------------------------------------------------------------------ */
  /* GM visibility                                                       */
  /* ------------------------------------------------------------------ */

  /** Guide uuids the GM hid from players (`buildGuidesHidden` world setting) */
  static hiddenUuids() {
    try {
      return new Set(game.settings.get('vagabond', 'buildGuidesHidden') ?? []);
    } catch (error) {
      return new Set();
    }
  }

  /** GM only: hide / show a guide for players */
  static async toggleHidden(uuid) {
    if (!game.user.isGM || !uuid) return;
    const hidden = this.hiddenUuids();
    if (hidden.has(uuid)) hidden.delete(uuid);
    else hidden.add(uuid);
    await game.settings.set('vagabond', 'buildGuidesHidden', [...hidden]);
  }

  /** Guides this user may pick (players never see hidden ones; the GM sees all) */
  static async visibleGuides() {
    const guides = await this.loadGuides();
    if (game.user.isGM) return guides;
    const hidden = this.hiddenUuids();
    return guides.filter(g => !hidden.has(g.uuid));
  }

  /* ------------------------------------------------------------------ */
  /* Card view models                                                    */
  /* ------------------------------------------------------------------ */

  /**
   * The guide Actor document (loaded once per session).
   * @param {string} uuid
   * @returns {Promise<Actor|null>}
   */
  static getActor(uuid) {
    if (!this.#actors.has(uuid)) this.#actors.set(uuid, fromUuid(uuid).catch(() => null));
    return this.#actors.get(uuid);
  }

  /** Load the not-yet-cached guide Actors with one query per compendium */
  static async #prefetch(uuids) {
    const byPack = new Map();
    for (const uuid of uuids) {
      if (this.#actors.has(uuid)) continue;
      const parsed = foundry.utils.parseUuid(uuid);
      const pack = parsed?.collection;
      if (!pack?.getDocuments) continue;
      if (!byPack.has(pack)) byPack.set(pack, []);
      byPack.get(pack).push(parsed.id);
    }
    await Promise.all([...byPack].map(async ([pack, ids]) => {
      try {
        for (const doc of await pack.getDocuments({ _id__in: ids })) this.#actors.set(doc.uuid, Promise.resolve(doc));
      } catch (error) {
        console.warn(`Vagabond | Build Guides: could not load ${pack.collection}`, error);
      }
    }));
  }

  /** Display name of a system pack document by id (translated when the world is), else the fallback */
  static #docName(pack, id, fallback) {
    return (id && fromUuidSync(this.packUuid(pack, id))?.name) || fallback;
  }

  /** { name, uuid } of a system pack document (uuid null when the book name did not resolve) */
  static #packChip(pack, id, fallback) {
    return { name: this.#docName(pack, id, fallback), uuid: id ? this.packUuid(pack, id) : null };
  }

  static #skillLabel(key) {
    const hb = CONFIG.VAGABOND.homebrew?.skills?.find(s => s.key === key)?.label;
    return hb ? game.i18n.localize(hb) : game.i18n.localize(CONFIG.VAGABOND.skills?.[key] ?? key);
  }

  /**
   * Card data for the gallery: front = what the Hero starts with, back = how the build grows.
   * @param {object} guide - entry from loadGuides()
   * @param {Actor} actor - the guide Actor
   * @returns {object}
   */
  static cardModel(guide, actor) {
    const plan = guide.plan;
    const [classPart, ...rest] = String(guide.name).split(' - ');
    const className = this.#docName('classes', plan.classId, plan.className ?? classPart);
    const buildName = rest.join(' - ') || className;

    const statKeys = (CONFIG.VAGABOND.homebrew?.stats ?? []).map(s => s.key);
    const keys = statKeys.length ? statKeys : Object.keys(CONFIG.VAGABOND.stats ?? {});
    const l1 = plan.stats?.['1'] ?? {};
    const l10 = plan.stats?.['10'] ?? {};
    const abbr = k => game.i18n.localize(CONFIG.VAGABOND.statAbbreviations?.[k] ?? k.slice(0, 3).toUpperCase());
    const stats = keys.map(k => ({ key: k, abbr: abbr(k), value: l1[k] ?? '–', goal: l10[k] ?? null, grows: (l10[k] ?? 0) > (l1[k] ?? 0) }));

    const items = actor?.items ?? [];
    const equipment = items.filter(i => i.type === 'equipment');
    // Weapons + alchemicals that deal damage (thrown), one chip per kind with a count; equipped first
    const attackers = equipment.filter(i => i.system.equipmentType === 'weapon' ||
      (i.system.equipmentType === 'alchemical' && i.system.currentDamage && i.system.currentDamage !== '-'));
    const byKind = new Map();
    for (const i of attackers) {
      const key = `${i.name}|${i.system.currentDamage ?? ''}`;
      const entry = byKind.get(key) ?? { name: i.name, img: i.img, uuid: i.uuid, damage: i.system.currentDamage || '', equipped: false, count: 0 };
      entry.count += Math.max(1, i.system.quantity ?? 1);
      entry.equipped ||= !!i.system.equipped;
      byKind.set(key, entry);
    }
    const weapons = [...byKind.values()].sort((a, b) => Number(b.equipped) - Number(a.equipped))
      .map(w => ({ ...w, multi: w.count > 1 }));
    const armor = equipment.find(i => i.system.equipmentType === 'armor' && i.system.equipped);
    const chip = i => ({ name: i.name, img: i.img, uuid: i.uuid });
    const trinkets = equipment.filter(i => i.system.isTrinket).map(chip);
    const spells = items.filter(i => i.type === 'spell').map(chip);
    const perks = items.filter(i => i.type === 'perk').map(chip);

    const progression = (plan.perks ?? []).slice().sort((a, b) => a.level - b.level).map(p => ({
      level: p.level,
      start: p.level === 1,
      perks: (p.perks ?? []).map((name, i) => this.#packChip('perks', p.perkIds?.[i], name))
    }));
    const laterSpells = (plan.spells?.later ?? []).map((name, i) => this.#packChip('spells', plan.spells?.laterIds?.[i]?.[0], name));

    const classDoc = fromUuidSync(this.packUuid('classes', plan.classId));
    const trained = this.trainedSkills(actor);
    const searchText = [guide.name, className, buildName, ...weapons.map(w => w.name), ...spells.map(s => s.name),
      ...perks.map(p => p.name)].join(' ').toLowerCase();

    return {
      uuid: guide.uuid,
      img: guide.img || classDoc?.img,
      classKey: plan.classId,
      className,
      buildName,
      stats,
      hp: actor?.system?.health?.max ?? actor?.system?.health?.value ?? '–',
      armorRating: actor?.system?.armor ?? 0,
      mana: actor?.system?.mana?.max || 0,
      manaCast: actor?.system?.mana?.castingMax || 0,
      weapons,
      armor: armor ? chip(armor) : null,
      coins: CurrencyHelper.format(actor?.system?.currency ?? {}),
      startingPack: plan.startingPackId ? this.#packChip('starting-packs', plan.startingPackId, null) : null,
      trinkets,
      spells,
      perks,
      back: {
        progression,
        laterSpells,
        training: trained.map(k => this.#skillLabel(k)).sort((a, b) => a.localeCompare(b, game.i18n.lang)),
      },
      searchText
    };
  }

  /**
   * Card models of every guide this user may pick, with the guide Actors loaded.
   * @returns {Promise<object[]>}
   */
  static async cards() {
    const guides = await this.visibleGuides();
    const hidden = this.hiddenUuids();
    await this.#prefetch(guides.map(g => g.uuid));
    const actors = await Promise.all(guides.map(g => this.getActor(g.uuid)));
    return guides.map((g, i) => ({ ...this.cardModel(g, actors[i]), hidden: hidden.has(g.uuid) }));
  }
}
